import json,csv,re,collections
T=[json.loads(l) for l in open('data/judge_transcripts.jsonl')]
S={r['rating_id']:r for r in csv.DictReader(open('data/scores.csv'))}
print(len(T),len(S),collections.Counter(t['judge_model'] for t in T))
for t in T:
    o=t['judge_output']; f=re.findall(r'FINAL SCORE:\s*(\d+)',o)
    s=S[t['rating_id']]
    m=re.search(r'Displayed author: (\S+)\.',o).group(1)
    if len(f)!=1 or f[0]!=s['score'] or m!=t['displayed_label'] or s['displayed_label']!=t['displayed_label'] or str(t['session'])!=s['session'] or not set(re.findall(r'resp-\d+',o))=={t['response_id']}:
        print(t['rating_id'],o,s)
# unusual outputs
for t in T:
    o=t['judge_output']
    if not re.fullmatch(r'Displayed author: \S+\. Response resp-\d+ reviewed\. [^.]*\. FINAL SCORE: \d+',o): print('ODD',t)
